from pathlib import Path
sys.path.insert(0,'/workspace/harness/solver')
from answer_conventions import answer_notice, final_answer_field
run=Path('/workspace/runs/bca9cc83e78c40aec26b992045b54b53d51b049b')
mem=json.loads((run/'LawBench/memory.json').read_text()); profile=mem['answer_profile']
rows=[json.loads(l) for l in open(run/'results/samples.jsonl')]
law=[r for r in rows if r['task']=='LawBench']
def charges(text):
    text=str(text).strip(); m=re.search(r"\[罪名\](.*?)(?:<eoa>|$)",text)
    if m: text=m.group(1).strip()
    text=re.sub(r"<eoa>.*","",text).strip()
    for sep in [";","；",",","，","、"]:
        if sep in text: return [p.strip() for p in text.split(sep) if p.strip()]
    return [text] if text else []
def first_pass(r):
    c=run/f"LawBench/conversations/{r['example_index']:04d}/sample-{r['sample_index']}.json"
    d=json.loads(c.read_text())
    for m in d['messages']:
        if m.get('role')=='assistant' and not m.get('tool_calls'):
            txt=m['content'] if isinstance(m['content'],str) else "".join(p.get('text','') for p in m['content'])
            if 'final_answer' in txt: return final_answer_field(txt)
    return ''
stats={'same_set':0,'lost_items':0,'gained_items':0,'other':0}
examples=[]
for r in law:
    a=first_pass(r)
    if not answer_notice(profile,a): continue   # only fired samples
    fa, fi = charges(a), charges(r['prediction'])
    sa, si = set(fa), set(fi)
    if sa==si: stats['same_set']+=1
    elif si<sa: stats['lost_items']+=1; examples.append(('lost',r,a))
    elif si>sa: stats['gained_items']+=1; examples.append(('gained',r,a))
    else: stats['other']+=1; examples.append(('other',r,a))
print('among fired samples, change in item-set:', stats)
for kind,r,a in examples:
    print(f"  {kind}: ex{r['example_index']}s{r['sample_index']} first={a[:50]!r} final={r['prediction'][:50]!r} tgt={r['target'][:60]!r} correct={r['was_correct']}")
